// Paginate through ALL conversations
const locationId = '9oW28j2SxdPAmUhO5MDI';
const allConversations = [];
let nextPage = null;

do {
  let url = `https://services.leadconnectorhq.com/conversations/search?locationId=${locationId}&limit=100`;
  if (nextPage) {
    url += `&startAfterId=${nextPage}`;
  }

  const response = await this.helpers.httpRequest({
    method: 'GET',
    url,
    headers: {
      'Authorization': 'Bearer pit-7af79179-2a7e-455f-a685-1b7c15d55547',
      'Version': '2021-07-28'
    },
    json: true
  });

  const conversations = response.conversations || [];
  allConversations.push(...conversations);
  nextPage = response.nextPage || null;

  if (nextPage) {
    await new Promise(resolve => setTimeout(resolve, 1000));
  }
} while (nextPage);

if (allConversations.length === 0) {
  throw new Error('No conversations found for this location.');
}

return allConversations.map(conv => ({
  json: {
    conversationId: conv.id,
    contactId: conv.contactId || '',
    locationId
  }
}));

// Fetch all messages for this conversation, paginated
const convData = $('Loop Conversations').first().json;
const conversationId = convData.conversationId;
const allMessages = [];
let lastMessageId = null;

do {
  let url = `https://services.leadconnectorhq.com/conversations/${conversationId}/messages`;
  if (lastMessageId) {
    url += `?lastMessageId=${lastMessageId}`;
  }

  let response;
  try {
    response = await this.helpers.httpRequest({
      method: 'GET',
      url,
      headers: {
        'Authorization': 'Bearer pit-7af79179-2a7e-455f-a685-1b7c15d55547',
        'Version': '2021-07-28'
      },
      json: true
    });
  } catch (e) {
    break;
  }

  let messages = [];
  if (Array.isArray(response.messages)) {
    messages = response.messages;
  } else if (response.messages && Array.isArray(response.messages.messages)) {
    messages = response.messages.messages;
  } else if (Array.isArray(response)) {
    messages = response;
  }

  allMessages.push(...messages);
  lastMessageId = response.lastMessageId || null;
  if (messages.length === 0) break;
  if (lastMessageId) {
    await new Promise(resolve => setTimeout(resolve, 500));
  }
} while (lastMessageId);

// Broad call detection — match every known GHL call type format
const validCalls = allMessages.filter(msg => {
  const msgType = (msg.type || '').toString();
  const msgMessageType = (msg.messageType || '').toString();
  const contentType = (msg.contentType || '').toString();
  const combined = `${msgType} ${msgMessageType} ${contentType}`.toLowerCase();

  const isCall =
    combined.includes('call') ||
    msgType === '3' ||
    msgMessageType === '3' ||
    msg.meta?.call != null ||
    msg.meta?.callDuration != null ||
    msg.meta?.recording != null ||
    msg.meta?.recordingUrl != null;

  if (!isCall) return false;

  // Duration check — try every known location, default to 0
  const duration =
    msg.meta?.call?.duration ||
    msg.meta?.callDuration ||
    msg.meta?.duration ||
    msg.duration ||
    msg.call?.duration ||
    0;
  return duration > 30;
});

// Collect debug info: all unique types seen (helps diagnose if 0 calls found)
const typeSet = new Set();
for (const msg of allMessages) {
  typeSet.add((msg.type || msg.messageType || 'UNKNOWN').toString());
}

if (validCalls.length === 0) {
  return [{
    json: {
      conversationId,
      contactId: convData.contactId,
      locationId: convData.locationId,
      hasValidCalls: false,
      validCalls: [],
      _debug_totalMessages: allMessages.length,
      _debug_uniqueTypes: [...typeSet]
    }
  }];
}

return [{
  json: {
    conversationId,
    contactId: convData.contactId,
    locationId: convData.locationId,
    hasValidCalls: true,
    validCalls: validCalls.map(c => {
      // Extract recording URL from every known location in the message
      const recUrl =
        c.meta?.recording ||
        c.meta?.recordingUrl ||
        c.meta?.recording_url ||
        c.meta?.call?.recording ||
        c.meta?.call?.recordingUrl ||
        c.meta?.call?.recording_url ||
        c.meta?.call?.recordingURL ||
        c.body ||
        c.attachments?.[0]?.url ||
        c.attachments?.[0] ||
        '';
      return {
        messageId: c.id,
        dateAdded: c.dateAdded || c.createdAt || '',
        duration: c.meta?.call?.duration || c.meta?.callDuration || c.meta?.duration || c.duration || 0,
        recordingUrl: typeof recUrl === 'string' && recUrl.startsWith('http') ? recUrl : '',
        _debug_meta: c.meta,
        _debug_body: c.body,
        _debug_attachments: c.attachments
      };
    }),
    _debug_totalMessages: allMessages.length,
    _debug_uniqueTypes: [...typeSet]
  }
}];

// Extract contact name, output each valid call as a separate item
const prevData = $('Has Valid Calls?').first().json;
const contactInput = $input.first().json;

// Robust contact name extraction — handle error responses and missing fields
const contact = contactInput.contact || contactInput;
const firstName = (contact.firstName || contact.first_name || contact.name || 'unknown').toString().toLowerCase().trim() || 'unknown';
const lastName = (contact.lastName || contact.last_name || '').toString().toLowerCase().trim() || 'unknown';

return prevData.validCalls.map((call, index) => {
  const callDate = new Date(call.dateAdded || new Date());
  const dateStr = callDate.toISOString().split('T')[0];
  // Include short messageId suffix to prevent duplicate filenames for same-day calls
  const idSuffix = (call.messageId || '').slice(-6);
  const filename = `${firstName}-${lastName}_${dateStr}_${idSuffix}`;

  return {
    json: {
      messageId: call.messageId,
      duration: call.duration,
      dateAdded: call.dateAdded,
      conversationId: prevData.conversationId,
      contactId: prevData.contactId,
      locationId: prevData.locationId,
      firstName,
      lastName,
      filename
    }
  };
});

// Use recording URL from message metadata first, fall back to API
const callData = $('Loop Calls').first().json;
const messageId = callData.messageId;
const locationId = callData.locationId;

// 1. Check if we already have a URL from the message metadata
let recordingUrl = callData.recordingUrl || '';
let responseData = null;

// 2. If no URL from metadata, try GHL API endpoints
if (!recordingUrl) {
  const urlPatterns = [
    `https://services.leadconnectorhq.com/conversations/messages/${messageId}/locations/${locationId}/recording`,
    `https://services.leadconnectorhq.com/conversations/messages/${messageId}/recording`,
    `https://services.leadconnectorhq.com/locations/${locationId}/recordings/${messageId}`
  ];

  for (const url of urlPatterns) {
    try {
      const response = await this.helpers.httpRequest({
        method: 'GET',
        url,
        headers: {
          'Authorization': 'Bearer pit-7af79179-2a7e-455f-a685-1b7c15d55547',
          'Version': '2021-07-28'
        },
        json: true
      });
      responseData = response;
      recordingUrl = response.url || response.recordingUrl || response.recording_url || response.data?.url || response.data?.recordingUrl || '';
      if (recordingUrl) break;
    } catch (e) {
      continue;
    }
  }
}

return [{
  json: {
    ...callData,
    recordingUrl,
    hasRecording: !!recordingUrl,
    _debug_recordingResponse: responseData,
    _debug_metaFromMessage: { meta: callData._debug_meta, body: callData._debug_body, attachments: callData._debug_attachments }
  }
}];

// Search for subaccount folder in Google Drive
const subaccountName = 'Strong Pilates Lakeview';
const callData = $('Has Recording?').first().json;

let folderId;
try {
  const searchResponse = await this.helpers.httpRequestWithAuthentication.call(
    this,
    'googleDriveOAuth2Api',
    {
      method: 'GET',
      url: 'https://www.googleapis.com/drive/v3/files',
      qs: {
        q: `mimeType='application/vnd.google-apps.folder' and name='${subaccountName}' and trashed=false`,
        fields: 'files(id,name)'
      },
      json: true
    }
  );

  const files = searchResponse.files || [];

  if (files.length > 0) {
    folderId = files[0].id;
  } else {
    const createResponse = await this.helpers.httpRequestWithAuthentication.call(
      this,
      'googleDriveOAuth2Api',
      {
        method: 'POST',
        url: 'https://www.googleapis.com/drive/v3/files',
        body: {
          name: subaccountName,
          mimeType: 'application/vnd.google-apps.folder'
        },
        json: true
      }
    );
    folderId = createResponse.id;
  }
} catch (e) {
  throw new Error(`Google Drive folder error: ${e.message}`);
}

return [{
  json: {
    ...callData,
    folderId,
    subaccountName
  },
  binary: $input.first().binary
}];

// Format ElevenLabs transcript into timestamped dialogue
const transcriptionData = $('Transcribe with ElevenLabs').first().json;
const callData = $('Get or Create Drive Folder').first().json;

const words = transcriptionData.words || [];

if (words.length === 0) {
  return [{
    json: {
      transcript: '(No speech detected)',
      filename: callData.filename,
      folderId: callData.folderId
    }
  }];
}

// Group words into utterances by speaker
const utterances = [];
let currentSpeaker = null;
let currentWords = [];
let currentStart = 0;

for (const word of words) {
  const speaker = word.speaker_id !== undefined ? word.speaker_id : (word.speaker ?? null);

  if (speaker !== currentSpeaker && currentWords.length > 0) {
    utterances.push({ speaker: currentSpeaker, text: currentWords.join(' '), start: currentStart });
    currentWords = [];
  }

  if (currentWords.length === 0) {
    currentStart = word.start_time || word.start || 0;
    currentSpeaker = speaker;
  }

  currentWords.push(word.text || word.word || '');
}

if (currentWords.length > 0) {
  utterances.push({ speaker: currentSpeaker, text: currentWords.join(' '), start: currentStart });
}

function formatTime(seconds) {
  const h = Math.floor(seconds / 3600).toString().padStart(2, '0');
  const m = Math.floor((seconds % 3600) / 60).toString().padStart(2, '0');
  const s = Math.floor(seconds % 60).toString().padStart(2, '0');
  return `[${h}:${m}:${s}]`;
}

const lines = utterances.map(u => {
  const speakerNum = parseInt(u.speaker, 10);
  const label = speakerNum === 0 ? 'Rep' : speakerNum === 1 ? 'Lead' : `Speaker ${u.speaker}`;
  return `${formatTime(u.start)} ${label}: ${u.text.trim()}`;
});

return [{
  json: {
    transcript: lines.join('\n'),
    filename: callData.filename,
    folderId: callData.folderId
  }
}];

// Convert transcript to binary TXT for upload
const data = $input.first().json;
const buffer = Buffer.from(data.transcript, 'utf-8');

return [{
  json: {
    filename: data.filename,
    folderId: data.folderId
  },
  binary: {
    transcriptFile: {
      data: buffer.toString('base64'),
      mimeType: 'text/plain',
      fileName: `${data.filename}_transcript.txt`
    }
  }
}];

// Rate limit between calls
await new Promise(resolve => setTimeout(resolve, 1000));
return $input.all();

// Restore binary recording data after Google Drive upload (which drops input binary)
const folderData = $('Get or Create Drive Folder').first();
return [{
  json: folderData.json,
  binary: folderData.binary
}];
